kevin: Python sketch (will be trimmed for docs):

```python
import time
import requests
from typing import Iterator, Optional

def retry_request(fn, attempts=3, base=0.2):
    for i in range(attempts):
        try:
            return fn()
        except requests.RequestException as e:
            if i == attempts - 1:
                raise
            time.sleep(base * (2 ** i))

def stream_with_resume(url: str, cursor: Optional[str] = None) -> Iterator[str]:
    params = {}
    if cursor:
        params['cursor'] = cursor
    resp = retry_request(lambda: requests.get(url, params=params, stream=True, timeout=10))
    for chunk in resp.iter_lines(decode_unicode=True):
        if not chunk:
            continue
        data = chunk.strip()
        # server may include a cursor header on reconnects
        if data.startswith('CURSOR:'):
            cursor = data.split(':',1)[1]
        else:
            yield data
```

